package dev.simplex.common;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Deterministic mapping between "slots" and the Java / Bedrock identifiers used to render them.
 *
 * <p>Custom blocks are rendered on Java by re-texturing block states of vanilla blocks that are
 * (practically) never generated by the game:
 * <ul>
 *   <li>{@link Kind#SOLID} – mushroom block states (brown/red caps with {@code down=true}, stems with
 *       {@code up} or {@code down} set). Full, opaque cubes with full collision. No note blocks.</li>
 *   <li>{@link Kind#TRANSPARENT} – chorus plant states with {@code down=false} and at least two horizontal
 *       connections. Non-occluding, cutout rendering: glass, grates, furniture-like block models.</li>
 * </ul>
 * The Geyser extension registers one Bedrock custom block per slot at Geyser start-up and overrides
 * exactly these Java states. Textures, geometry, names and sounds are looked up through texture keys that
 * only the (re-generated) Bedrock resource pack resolves, so new blocks can be added at runtime and Bedrock
 * players only have to reconnect.
 *
 * <p>Items work the same way: item slot {@code N} uses the Java item model {@code simplex:slot_N} which the
 * Java resource pack points to the real model, and Geyser maps that item model to the Bedrock item
 * {@code geyser_custom:simplex_iN}.
 */
public final class SlotLayout {

    /** Number of item slots (shared by block items and 3D model items). Must match on plugin and extension. */
    public static final int ITEM_SLOTS = 512;

    /** Vanilla Java item every custom item is based on. */
    public static final String BASE_ITEM = "minecraft:paper";

    public static final String NAMESPACE = "simplex";

    /** Bedrock face names in the order used for material instances. */
    public static final List<String> FACES = List.of("up", "down", "north", "south", "east", "west");

    /** Property order of {@code MultipleFacing} blocks in Java state strings (alphabetical). */
    private static final String[] PROPS = {"down", "east", "north", "south", "up", "west"};
    private static final int DOWN = 1, EAST = 1 << 1, NORTH = 1 << 2, SOUTH = 1 << 3, UP = 1 << 4, WEST = 1 << 5;

    public enum Kind { SOLID, TRANSPARENT }

    /**
     * @param index    global slot index
     * @param kind     render kind
     * @param block    vanilla block id without namespace, e.g. {@code brown_mushroom_block}
     * @param mask     face bit mask (bit 0 = down, 1 = east, 2 = north, 3 = south, 4 = up, 5 = west)
     */
    public record BlockSlot(int index, Kind kind, String block, int mask) {
        /** Full Java block state string, e.g. {@code minecraft:brown_mushroom_block[down=true,east=false,...]}. */
        public String javaState() { return stateString(block, mask); }
        public String bedrockName() { return "simplex_b" + index; }
        public String bedrockIdentifier() { return "geyser_custom:" + bedrockName(); }
        public String textureKey(String face) { return bedrockName() + "_" + face; }
        public String geometryIdentifier() { return "geometry.simplex.b" + index; }
        public String nameKey() { return "simplex.block.b" + index; }
    }

    private static final List<BlockSlot> BLOCK_SLOTS;
    private static final BlockSlot[][] BY_BLOCK_MASK = new BlockSlot[4][64];
    private static final String[] BLOCKS = {"brown_mushroom_block", "red_mushroom_block", "mushroom_stem", "chorus_plant"};

    static {
        List<BlockSlot> slots = new ArrayList<>();
        int index = 0;
        // Solid: brown + red mushroom caps with down=true (never generated naturally), excluding the all-true default.
        for (int b = 0; b < 2; b++) {
            for (int mask = 0; mask < 64; mask++) {
                if ((mask & DOWN) != 0 && mask != 63) {
                    BlockSlot slot = new BlockSlot(index++, Kind.SOLID, BLOCKS[b], mask);
                    slots.add(slot);
                    BY_BLOCK_MASK[b][mask] = slot;
                }
            }
        }
        // Solid: mushroom stems with up or down set (natural stems always have up=false, down=false).
        for (int mask = 0; mask < 64; mask++) {
            if ((mask & (UP | DOWN)) != 0 && mask != 63) {
                BlockSlot slot = new BlockSlot(index++, Kind.SOLID, BLOCKS[2], mask);
                slots.add(slot);
                BY_BLOCK_MASK[2][mask] = slot;
            }
        }
        // Transparent: chorus plants without a downward connection and >= 2 horizontal connections.
        for (int mask = 0; mask < 64; mask++) {
            if ((mask & DOWN) == 0 && horizontal(mask) >= 2) {
                BlockSlot slot = new BlockSlot(index++, Kind.TRANSPARENT, BLOCKS[3], mask);
                slots.add(slot);
                BY_BLOCK_MASK[3][mask] = slot;
            }
        }
        BLOCK_SLOTS = Collections.unmodifiableList(slots);
    }

    private SlotLayout() {}

    private static int horizontal(int mask) {
        return Integer.bitCount(mask & (EAST | NORTH | SOUTH | WEST));
    }

    public static List<BlockSlot> blockSlots() { return BLOCK_SLOTS; }

    public static BlockSlot blockSlot(int index) {
        return index >= 0 && index < BLOCK_SLOTS.size() ? BLOCK_SLOTS.get(index) : null;
    }

    public static int blockIndex(String block) {
        for (int i = 0; i < BLOCKS.length; i++) if (BLOCKS[i].equals(block)) return i;
        return -1;
    }

    /** Looks up the slot for a vanilla block id (without namespace) and face mask; {@code null} if not reserved. */
    public static BlockSlot find(String block, int mask) {
        int b = blockIndex(block);
        if (b < 0 || mask < 0 || mask > 63) return null;
        return BY_BLOCK_MASK[b][mask];
    }

    /** Whether the block uses multiple-facing states that we may reserve. */
    public static boolean isHostBlock(String block) { return blockIndex(block) >= 0; }

    public static int mask(boolean down, boolean east, boolean north, boolean south, boolean up, boolean west) {
        return (down ? DOWN : 0) | (east ? EAST : 0) | (north ? NORTH : 0) | (south ? SOUTH : 0) | (up ? UP : 0) | (west ? WEST : 0);
    }

    /** Whether the face with the given property name is set in the mask. */
    public static boolean has(int mask, String face) {
        for (int i = 0; i < PROPS.length; i++) if (PROPS[i].equals(face)) return (mask & (1 << i)) != 0;
        return false;
    }

    public static String stateString(String block, int mask) {
        StringBuilder sb = new StringBuilder("minecraft:").append(block).append('[');
        for (int i = 0; i < PROPS.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(PROPS[i]).append('=').append((mask & (1 << i)) != 0);
        }
        return sb.append(']').toString();
    }

    /** Blockstate variant key used in Java resource packs, e.g. {@code down=true,east=false,...}. */
    public static String variantKey(int mask) {
        String s = stateString("x", mask);
        return s.substring(s.indexOf('[') + 1, s.length() - 1);
    }

    public static List<String> hostBlocks() { return List.of(BLOCKS); }

    // ---- items ---------------------------------------------------------------------------------------------

    public static String itemModel(int slot) { return NAMESPACE + ":slot_" + slot; }
    public static String itemModelPath(int slot) { return "slot_" + slot; }
    public static String bedrockItemName(int slot) { return "simplex_i" + slot; }
    public static String bedrockItemIdentifier(int slot) { return "geyser_custom:" + bedrockItemName(slot); }
    public static String itemIconKey(int slot) { return bedrockItemName(slot); }
    public static String itemGeometry(int slot) { return "geometry.simplex.i" + slot; }
}
